<script setup lang="ts">
import { computed, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { runCrossTabComparison, type CrossTabRun, type JobOwnershipPort } from '@concurrency-lab/scenario-engine'
const { locale } = useI18n(); const comparison = ref<ReturnType<typeof runCrossTabComparison> | null>(null); const owner = ref(''); const backUrl = `${import.meta.env.BASE_URL}scenarios`; const tabId = new URLSearchParams(window.location.search).get('tab') ?? crypto.randomUUID().slice(0, 8); const fa = computed(() => locale.value === 'fa')
const ownership: JobOwnershipPort = { claim(jobId, claimant) { const key = `concurrency-lab:${jobId}:owner:v1`; const existing = localStorage.getItem(key); if (!existing) localStorage.setItem(key, claimant); return localStorage.getItem(key) ?? claimant } }
function coordinate() { comparison.value = runCrossTabComparison('v1'); owner.value = ownership.claim('fixture-job', tabId) }
function label(event: { kind: string; label: string }) { if (!fa.value) return event.label; return ({ request: 'تب اعلام آمادگی کرد', acquire: 'یک تب مالک شد', discard: 'تب دیگر follower ماند', commit: 'تب مالک job را اجرا کرد', invariant: 'قانون مالکیت ارزیابی شد' } as Record<string, string>)[event.kind] ?? event.kind }
</script>
<template><article><section class="detail-hero"><a class="back-link" :href="backUrl">{{fa?'بازگشت →':'← Back'}}</a><p class="eyebrow">{{fa?'سناریوی ۰۵ · مالکیت میان تب‌ها':'Scenario 05 · Cross-tab ownership'}}</p><h1>{{fa?'یک کار، یک تب مالک':'One job, one owning tab'}}</h1><p>{{fa?'این صفحه علاوه بر ردیابی آموزشی، با localStorage مشترک واقعاً میان تب‌های همین origin مالک را ثبت می‌کند. در محصول واقعی heartbeat، lease و crash recovery نیز لازم‌اند.':'Besides the teaching trace, this page uses shared same-origin localStorage to claim one owner across real tabs. Production systems also need heartbeats, leases, and crash recovery.'}}</p></section><section class="comparison-controls"><p>Tab <code>{{tabId}}</code></p><button class="primary-action" @click="coordinate">{{fa?'هماهنگی این تب':'Coordinate this tab'}}</button><p v-if="owner" :class="owner===tabId?'pass-label':'count-badge'">{{owner===tabId?(fa?'این تب مالک است':'This tab owns the job'):(fa?`تب ${owner} مالک است؛ این تب follower است`:`Tab ${owner} owns the job; this tab is a follower`)}}</p></section><section v-if="comparison" class="comparison-results"><div class="comparison-grid"><article v-for="lane in ([comparison.broken,comparison.fixed] as CrossTabRun[])" :key="lane.variant" class="result-panel" :class="lane.variant==='broken'?'lane-broken':'lane-fixed'"><h2>{{lane.variant==='broken'?(fa?'ادعای مستقل':'Independent claims'):(fa?'انتخاب رهبر':'Leader election')}}</h2><p :class="lane.invariant.passed?'pass-label':'failure-badge'">{{lane.invariant.passed?(fa?'یک مالک':'One owner'):(fa?'مالک تکراری':'Duplicate owners')}}</p><ol class="timeline"><li v-for="e in lane.events" :key="e.sequence"><span class="sequence">{{e.sequence}}</span><span class="event-time">{{e.timestamp}}ms</span><strong>{{label(e)}}</strong><span class="event-kind">{{e.kind}}</span></li></ol></article></div></section></article></template>
